// ─── Secret ──────────────────────────────────────────────────────

export interface Secret {
  id: string
  workspaceId: string
  /**
   * A label people pick a secret from, never an environment variable key: a
   * secret is referenced by id (`secret:<id>#field`), and the env key, if one
   * is ever needed, belongs on the binding. Shaped as a DNS-1123 subdomain
   * (the Kubernetes Secret-name rule), so what one screen writes another can
   * quote in a path, a flag or a hostname without escaping.
   */
  name: string
  kind: SecretKind
  /** @encrypted */
  data: string
  verifiedAt?: string | null
  verifyError?: string | null
  createdBy?: string | null
  /**
   * WHICH vendor a `provider_key` opens — a cloud, an edge or a forge. Null
   * for every other kind.
   * 
   * It is a column rather than a field inside `data` because a vendor name is
   * not a secret: `data` is `@encrypted`, so the key is absent from every read,
   * and *which DigitalOcean accounts does this workspace have* would mean
   * decrypting every secret in the workspace to answer. Here it filters, it
   * indexes, and it reaches a picker as a set.
   * 
   * It is `ProviderKind`, the whole vendor catalogue, rather than a second
   * vendor vocabulary on `SecretKind`: a key names a vendor whatever role it
   * plays. `Server.providerKind` narrows it to `ComputeProvider` (FJS-D1607).
   */
  providerKind?: ProviderKind | null
  /** @version */
  version: number
  createdAt: string
  updatedAt: string
  deletedAt?: string | null
}

